# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: which characters and stages a player picks, counted from their recent start.gg
# sets: overall, per event, in game 1, after losing / winning the game before, and how often
# they change character within a set. Optionally only games against one character.
# Facts only: PlayerUsage carries no result (no wins, scores, seeds, placements); the game
# winners are read here only to tell a counterpick from a starter. Results: results.py.
# Usage: `usage = asyncio.run(player_usage("Sparg0", vs_characters=["steve", "pac_man"]))`
# ---------------------------------------------------------------------------
from __future__ import annotations

import datetime as dt
from collections import Counter
from typing import TYPE_CHECKING, Literal

from pydantic import BaseModel, Field

from ds.data.chars import CharGroup
from ds.data.raw import startgg
from ds.data.raw.startgg import queries
from ds.data.raw.startgg.characters import stored_characters
from ds.data.startgg.lookup import PlayerLookup, resolve_player

if TYPE_CHECKING:
    from ds.data.raw.startgg import Character, Game, Set

__all__ = [
    "CharacterStats",
    "CharacterUsage",
    "EventCharacter",
    "EventCharacters",
    "PlayerUsage",
    "RecentEvents",
    "SetCount",
    "Setting",
    "StageStats",
    "StageUsage",
    "Switches",
    "UsageWindow",
    "player_usage",
    "usage_from_sets",
]

# The window: the newest sets one start.gg request returns (USAGE_PAGES requests of
# api.USAGE_PER_PAGE = 30 sets, singles only), not a span of months. Recent trends over
# history, and as few requests as possible: one request is about 23-29 Ultimate sets, 3-4
# events (Sparg0, rm8; Nov 2026). Raise USAGE_PAGES to look further back (~30 sets each).
USAGE_PAGES = 1
# The sets a caller can ask for (the agent tool's and the app form's `sets` input): one
# start.gg request per 30, so the choice shows its cost. 150 was the old window (14-18
# requests then, 5 now).
SetCount = Literal[30, 60, 90, 120, 150]
# Which events count: every one, only in-person ones, or only online ones (start.gg's isOnline)
Setting = Literal["all", "offline", "online"]
_ONLINE: dict[str, bool | None] = {"all": None, "offline": False, "online": True}
EVENTS = 10


class CharacterUsage(BaseModel):
    """One character's share of a count (games, or events)"""

    char_group: str | None = Field(None, description="char.parquet `char_group`, eg 'cloud', 'pokemon_trainer'")
    character: str = Field(description="Name as start.gg shows it, eg 'Little Mac', 'Pokemon Trainer'")
    char_icon: str | None = Field(None, description="Icon path under pkgs/ds/data/")
    usage_pct: float = Field(description="0-100, `count` / the stats' `total`")
    count: int = Field(description="Games (or events, if unit='events') this character was used in")


class CharacterStats(BaseModel):
    """Character usage over one set of games (or events), most-used first"""

    # with events a player can use several characters at one event: usage_pct can pass 100
    unit: Literal["games", "events"] = Field(description="What `total` / `count` count; events: pct can pass 100")
    total: int = Field(description="Games (or events) with character data")
    characters: list[CharacterUsage]


class StageUsage(BaseModel):
    """One stage's share of the games in a stage category"""

    stage: str = Field(description="Name as start.gg shows it, eg 'Pokémon Stadium 2'")
    usage_pct: float = Field(description="0-100, share of the category's games that have a stage")
    games: int


class StageStats(BaseModel):
    """Stage usage for one category, most-played first. Often empty: stages go unreported"""

    games: int = Field(description="Games in this category that have a stage reported")
    stages: list[StageUsage]


class EventCharacter(BaseModel):
    """A character used at one event, with how many games"""

    char_group: str | None = None
    character: str
    char_icon: str | None = None
    games: int


class EventCharacters(BaseModel):
    """The characters a player used at one tournament event"""

    date: dt.date = Field(description="Date of the player's last set there")
    tournament: str = Field(description="Tournament name, eg 'Midnight Mashers #462'")
    event: str = Field(description="Event name within the tournament, eg 'Ultimate Singles'")
    online: bool | None = None
    url: str | None = Field(None, description="The event's start.gg page")
    characters: list[EventCharacter] = Field(description="Most games first; [] = no character data reported")


class RecentEvents(BaseModel):
    """Character usage over the player's last events in the window, counted per event"""

    first_date: dt.date | None = Field(None, description="Oldest listed event's date")
    last_date: dt.date | None = Field(None, description="Newest listed event's date")
    characters: CharacterStats = Field(description="unit='events': in how many of these events each was used")
    events: list[EventCharacters] = Field(description="Newest first")


class Switches(BaseModel):
    """How often the player changed character from one game of a set to the next"""

    sets: int = Field(description="Sets with character data for at least two games")
    sets_with_switch: int = Field(description="Of those, sets where they changed character at least once")
    chances_after_losing: int = Field(description="Games that followed a game they lost (character data on both)")
    switched_after_losing: int = Field(description="Of those, games where they came back as another character")
    chances_after_winning: int = Field(description="Games that followed a game they won")
    switched_after_winning: int = Field(description="Of those, games where they changed character anyway")


class UsageWindow(BaseModel):
    """What the numbers are based on. Always tell the user the real date span and counts"""

    requests: int = Field(description="start.gg requests for sets: each reads the newest ~30 sets")
    events: int = Field(description="Events the counted sets come from")
    sets: int = Field(description="Sets counted (with `vs_characters`: sets with a game against one of them)")
    games: int = Field(description="Games counted: those with the player's character reported")
    first_date: dt.date | None = Field(None, description="Oldest counted set's date")
    last_date: dt.date | None = Field(None, description="Newest counted set's date")


class PlayerUsage(BaseModel):
    """A player's character and stage picks over their recent start.gg sets"""

    lookup: PlayerLookup = Field(description="Which player this is and how the input was matched")
    vs_characters: list[CharGroup] = Field(
        default_factory=list, description="The opponent's picks the games were narrowed to ([] = every game)"
    )
    setting: Setting = Field("all", description="Which events were counted: all, offline (in person) or online")
    window: UsageWindow
    recent: CharacterStats = Field(description="Every counted game in the window")
    game_1: CharacterStats = Field(description="Their character in game 1 of a set (what they open with)")
    last_events: RecentEvents
    starters: StageStats = Field(description="Stages of game 1")
    counterpicks: StageStats = Field(description="Stages of games right after a game they lost (their pick)")
    taken_to: StageStats = Field(description="Stages of games right after a game they won (the opponent's pick)")
    switches: Switches


def _character_stats(counts: Counter[int], seen: dict[int, Character], unit: str, total: int) -> CharacterStats:
    characters = [
        CharacterUsage(
            char_group=seen[key].char_group,
            character=seen[key].name,
            char_icon=seen[key].char_icon,
            usage_pct=count / total * 100 if total else 0.0,
            count=count,
        )
        for key, count in counts.most_common()
    ]
    return CharacterStats(unit=unit, total=total, characters=characters)


def _stage_stats(counts: Counter[str]) -> StageStats:
    total = sum(counts.values())
    stages = [
        StageUsage(stage=name, usage_pct=games / total * 100, games=games) for name, games in counts.most_common()
    ]
    return StageStats(games=total, stages=stages)


def _one_of(character: Character | None, groups: list[CharGroup]) -> bool:
    return bool(character and character.char_group in groups)


def usage_from_sets(  # one pass over the games, counting several things
    sets: list[Set],
    lookup: PlayerLookup,
    *,
    vs_characters: list[CharGroup] | None = None,
    setting: Setting = "all",
    requests: int = USAGE_PAGES,
    events: int = EVENTS,
) -> PlayerUsage:
    """Count a player's picks over sets already fetched (newest first); see `player_usage`

    Args:
        sets: the player's sets, eg from `ds.data.raw.startgg.player_sets`.
        lookup: who the player is (`lookup.player_id` finds their side of each set).
        vs_characters: only games where the opponent picked one of these are counted.
        setting: which events `sets` was fetched for; recorded in the result, not applied.
        requests: how many requests fetched `sets`, recorded in `window`.
        events: how many of the newest events to list in `last_events`.
    """
    player_id = lookup.player_id
    seen: dict[int, Character] = {}
    recent: Counter[int] = Counter()
    game_1: Counter[int] = Counter()
    stages: dict[str, Counter[str]] = {"starters": Counter(), "counterpicks": Counter(), "taken_to": Counter()}
    switch = Counter()
    per_event: dict[int, tuple[EventCharacters, Counter[int]]] = {}
    counted_sets: list[Set] = []

    for s in sets:
        mine, theirs = s.side_of(player_id), s.opponent_of(player_id)
        if mine is None or s.completed_at is None:
            continue
        by_number = {g.number: g for g in s.games}
        set_counted, picks_in_set, switched_in_set = False, 0, False
        event_counts: Counter[int] = Counter()
        for game in s.games:
            character = game.character_of(mine.entrant_id)
            opponent = game.character_of(theirs.entrant_id) if theirs else None
            if vs_characters and not _one_of(opponent, vs_characters):
                continue
            set_counted = True
            before: Game | None = by_number.get(game.number - 1)
            lost_before = before is not None and before.winner_entrant_id not in {None, mine.entrant_id}
            won_before = before is not None and before.winner_entrant_id == mine.entrant_id
            if game.stage:
                kind = "starters" if game.number == 1 else "counterpicks" if lost_before else "taken_to"
                if game.number == 1 or lost_before or won_before:
                    stages[kind][game.stage.name] += 1
            if character is None:
                continue
            seen[character.id] = character
            recent[character.id] += 1
            event_counts[character.id] += 1
            picks_in_set += 1
            if game.number == 1:
                game_1[character.id] += 1
            previous = before.character_of(mine.entrant_id) if before else None
            if previous is not None and (lost_before or won_before):
                when = "losing" if lost_before else "winning"
                switch[f"chances_after_{when}"] += 1
                if previous.id != character.id:
                    switch[f"switched_after_{when}"] += 1
                    switched_in_set = True
        if vs_characters and not set_counted:
            continue
        counted_sets.append(s)
        if picks_in_set > 1:
            switch["sets"] += 1
            switch["sets_with_switch"] += switched_in_set
        if s.event:
            if s.event.id not in per_event:
                row = EventCharacters(
                    date=s.completed_at.date(),
                    tournament=s.event.tournament.name if s.event.tournament else "",
                    event=s.event.name,
                    online=s.event.online,
                    url=f"{startgg.SITE_URL}/{s.event.slug}" if s.event.slug else None,
                    characters=[],
                )
                per_event[s.event.id] = (row, Counter())
            per_event[s.event.id][1].update(event_counts)

    newest = sorted(per_event.values(), key=lambda pair: pair[0].date, reverse=True)[:events]
    event_rows, used_at = [], Counter()
    for row, counts in newest:
        row.characters = [
            EventCharacter(char_group=seen[k].char_group, character=seen[k].name, char_icon=seen[k].char_icon, games=n)
            for k, n in counts.most_common()
        ]
        used_at.update(counts.keys())
        event_rows.append(row)
    with_data = sum(1 for row in event_rows if row.characters)
    dates = [s.completed_at.date() for s in counted_sets if s.completed_at]
    return PlayerUsage(
        lookup=lookup,
        vs_characters=vs_characters or [],
        setting=setting,
        window=UsageWindow(
            requests=requests,
            events=len(per_event),
            sets=len(counted_sets),
            games=sum(recent.values()),
            first_date=min(dates, default=None),
            last_date=max(dates, default=None),
        ),
        recent=_character_stats(recent, seen, "games", sum(recent.values())),
        game_1=_character_stats(game_1, seen, "games", sum(game_1.values())),
        last_events=RecentEvents(
            first_date=event_rows[-1].date if event_rows else None,
            last_date=event_rows[0].date if event_rows else None,
            characters=_character_stats(used_at, seen, "events", with_data),
            events=event_rows,
        ),
        starters=_stage_stats(stages["starters"]),
        counterpicks=_stage_stats(stages["counterpicks"]),
        taken_to=_stage_stats(stages["taken_to"]),
        switches=Switches(**{name: switch[name] for name in Switches.model_fields}),
    )


def vs_char_group(character: CharGroup | str) -> CharGroup:
    """A pick given as a CharGroup, an id or a name ('pt_ivysaur', 'Pokemon Trainer')

    Raises ValueError naming what was given when it is no character.
    """
    try:
        return CharGroup(character)
    except ValueError:
        raise ValueError(f"unknown character {character!r}; give a pick, eg 'little_mac', 'pokemon_trainer'") from None


async def player_usage(
    player: str,
    vs_characters: list[CharGroup | str] | None = None,
    requests: int = USAGE_PAGES,
    events: int = EVENTS,
    setting: Setting = "all",
) -> PlayerUsage:
    """A player's character and stage picks over their newest start.gg sets (facts, no results)

    Covers the newest Ultimate singles sets `requests` start.gg requests return (about 30 each,
    fewer once other games are left out); `window` says what that came to. Raises
    PlayerLookupError for an unknown player and ValueError for an unknown character.

    Args:
        player: a tag ('Sparg0'), start.gg player id ('158026') or start.gg profile url.
        vs_characters: only games against one of these picks are counted: `CharGroup`s, or
            ids / names they parse ('steve', 'Pokemon Trainer'; 'pt_ivysaur' means its group).
        requests: how many requests' worth of sets to read (each ~30, newest first).
        events: how many of the newest events to list.
        setting: 'offline' for in-person events only, 'online' for online only, 'all' for both.
            start.gg filters, so 'offline' still gets a full request of in-person sets.
    """
    if setting not in _ONLINE:
        raise ValueError(f"setting must be one of {list(_ONLINE)}, got {setting!r}")
    vs = list(dict.fromkeys(vs_char_group(c) for c in vs_characters or []))  # in order, once each
    lookup = await resolve_player(player)
    per_page = startgg.USAGE_PER_PAGE
    sets = await startgg.player_sets(
        lookup.player_id,
        max_sets=requests * per_page,
        per_page=per_page,
        max_pages=requests,
        online=_ONLINE[setting],
        query=queries.USAGE_SETS,
        # stored, so no request is spent on them (fetched once if the table isn't there)
        characters=stored_characters(),
    )
    return usage_from_sets(sets, lookup, vs_characters=vs, setting=setting, requests=requests, events=events)
